sys_script.script:
(function executeRule(current, previous) {
    if (previous.verbatim_comments &&
        previous.verbatim_comments.toString().trim() !== '') {

        current.setAbortAction(true);

        gs.addErrorMessage(
            'AEGIS Governance: Submitted panellist feedback comments are immutable and cannot be altered.'
        );
    }
})(current, previous);
